import select
import threading
import paramiko
import logging
import socketserver


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ForwardServer(socketserver.ThreadingTCPServer):
    daemon_threads = True
    allow_reuse_address = True


class Handler(socketserver.BaseRequestHandler):
    def handle(self):

        channel = self.open_channel()

        if channel is None:
            logger.info("Incoming request to {}:{} was rejected by the SSH server."
                        .format(self.chain_host, self.chain_port)
                        )
            return

        logger.info("Connected!  Tunnel open {} -> {} -> {}".format(self.request.getpeername(),
                                                                    channel.getpeername(),
                                                                    (self.chain_host, self.chain_port),)
                    )

        ready = False
        while not ready:
            ready = self.wait_for_tunnel(channel)

        try:
            peername = self.request.getpeername()
            channel.close()
            self.request.close()
            logger.info("Tunnel closed from %r" % (peername,))
        except OSError as e:
            logger.info(str(e))

    def open_channel(self):
        try:
            chanell = self.ssh_transport.open_channel(
                "direct-tcpip",
                (self.chain_host, self.chain_port),
                self.request.getpeername(),
            )
            return chanell
        except Exception as e:
            logger.info("Incoming request to %s:%d failed: %s"
                        % (self.chain_host, self.chain_port, repr(e)))
            return

    def wait_for_tunnel(self, channel):
        r, _, _ = select.select([self.request, channel], [], [])
        if self.request in r:
            try:
                data = self.request.recv(1024)
            except ConnectionResetError as e:
                logger.info(str(e))
                return True
            if len(data) == 0:
                return True
            channel.send(data)

        if channel in r:
            data = channel.recv(1024)
            if len(data) == 0:
                return True
            self.request.send(data)

        return False


class RemoteConnection():

    def __init__(self, ssh_host, ssh_port, ssh_username, ssh_password):
        # SSH details
        self.ssh_host = ssh_host
        self.ssh_port = ssh_port
        self.ssh_username = ssh_username
        self.ssh_password = ssh_password

        self.forward_tunnel_thread = None
        self.forward_server = None
        self.server_stop = True

        # Establish SSH connection
        self.ssh_client = paramiko.SSHClient()
        self.ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        self.ssh_client.connect(self.ssh_host, self.ssh_port, self.ssh_username, self.ssh_password)
        self.ssh_transport = self.ssh_client.get_transport()

    def setup_tunnel(self, remote_host="192.168.255.129", remote_port=443, local_host="localhost", local_port=8888):
        self.forward_tunnel_thread = threading.Thread(target=self._forward_tunnel,
                                                      args=[remote_host, remote_port, local_host, local_port])
        self.forward_tunnel_thread.setDaemon(True)
        self.forward_tunnel_thread.start()
        logger.info("Forward server to {}:{} setup on {}:{}".format(remote_host, remote_port, local_host, local_port))

    def _forward_tunnel(self, remote_host, remote_port, local_host, local_port):
        # this is a little convoluted, but lets me configure things for the Handler
        # object.  (socketserver doesn't give Handlers any way to access the outer
        # server normally.)
        class SubHander(Handler):
            chain_host = remote_host
            chain_port = remote_port
            ssh_transport = self.ssh_transport

        self.forward_server = ForwardServer((local_host, local_port), SubHander)
        self.forward_server.serve_forever()

    def close(self):
        # Close the SSH connection
        self.forward_server.shutdown()
        self.forward_tunnel_thread.join(timeout=5)
        self.ssh_client.close()
